<?php
require_once 'functions.php';require_login();$id=uid();$error='';$cats=['Salary','Freelancing','Business','Investment','Food','Transport','Shopping','Bills','Education','Health','Entertainment','Rent','Subscriptions','Other'];
if($_SERVER['REQUEST_METHOD']==='POST'){$act=$_POST['action']??'';if($act==='delete'){$s=$pdo->prepare('DELETE FROM transactions WHERE id=? AND user_id=?');$s->execute([(int)$_POST['id'],$id]);header('Location: transactions.php?deleted=1');exit;}if(in_array($act,['add','edit'],true)){$type=$_POST['type']??'';$cat=trim($_POST['category']??'');$amt=filter_var($_POST['amount']??'',FILTER_VALIDATE_FLOAT);$date=$_POST['transaction_date']??'';$desc=trim($_POST['description']??'');$d=DateTime::createFromFormat('Y-m-d',$date);if(!in_array($type,['income','expense'],true)||$cat===''||$amt===false||$amt<=0||!$d||$d->format('Y-m-d')!==$date)$error='Enter a valid type, category, positive amount and date.';else{if($act==='add'){$s=$pdo->prepare('INSERT INTO transactions(user_id,type,category,amount,transaction_date,description) VALUES(?,?,?,?,?,?)');$s->execute([$id,$type,$cat,$amt,$date,$desc]);}else{$s=$pdo->prepare('UPDATE transactions SET type=?,category=?,amount=?,transaction_date=?,description=? WHERE id=? AND user_id=?');$s->execute([$type,$cat,$amt,$date,$desc,(int)$_POST['id'],$id]);}header('Location: transactions.php?saved=1');exit;}}}
$edit=null;if(($_GET['action']??'')==='edit'){$s=$pdo->prepare('SELECT * FROM transactions WHERE id=? AND user_id=?');$s->execute([(int)($_GET['id']??0),$id]);$edit=$s->fetch();}$q=trim($_GET['q']??'');$tf=$_GET['type']??'';$cf=$_GET['category']??'';$sql='SELECT * FROM transactions WHERE user_id=?';$p=[$id];if($q!==''){$sql.=' AND (description LIKE ? OR category LIKE ?)';$p[]="%$q%";$p[]="%$q%";}if(in_array($tf,['income','expense'],true)){$sql.=' AND type=?';$p[]=$tf;}if($cf!==''){$sql.=' AND category=?';$p[]=$cf;}$sql.=' ORDER BY transaction_date DESC,id DESC';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();
start_page('Transactions','transactions.php');?>
<div class="page-intro"><div><h1>Transactions</h1><p>Every income and expense, all in one place.</p></div><a class="primary" href="#tx-form">＋ New transaction</a></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert success">Transaction saved successfully.</div><?php endif;?><?php if(isset($_GET['deleted'])):?><div class="alert success">Transaction deleted.</div><?php endif;?>
<section class="panel" id="tx-form"><div class="panel-head"><div><h2><?=$edit?'Edit transaction':'Add a transaction'?></h2><p>Keep the details clear and accurate.</p></div><span class="round-icon">✦</span></div><form method="post" class="form-grid"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif;?><label>Type<select name="type"><option value="expense" <?=($edit['type']??'expense')==='expense'?'selected':''?>>Expense</option><option value="income" <?=($edit['type']??'')==='income'?'selected':''?>>Income</option></select></label><label>Category<select name="category"><?php foreach($cats as $c):?><option <?=($edit['category']??'Food')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label>Amount (<?=e(csym())?>)<input type="number" name="amount" min=".01" step=".01" required value="<?=e((string)($edit['amount']??''))?>" placeholder="0.00"></label><label>Date<input type="date" name="transaction_date" required value="<?=e($edit['transaction_date']??date('Y-m-d'))?>"></label><label class="span2">Description<input name="description" maxlength="255" value="<?=e($edit['description']??'')?>" placeholder="What was this transaction for?"></label><div class="span2 actions"><button class="primary"><?=$edit?'Save changes':'Add transaction'?> →</button><?php if($edit):?><a class="soft-button" href="transactions.php">Cancel</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-head"><div><h2>All activity</h2><p><?=count($rows)?> transaction(s) found</p></div></div><form method="get" class="filters"><input name="q" value="<?=e($q)?>" placeholder="⌕ Search description or category"><select name="type"><option value="">All types</option><option value="income" <?=$tf==='income'?'selected':''?>>Income</option><option value="expense" <?=$tf==='expense'?'selected':''?>>Expense</option></select><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=$cf===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="soft-button">Filter</button><a class="soft-button" href="transactions.php">Reset</a></form><?php if(!$rows):?><div class="empty">No transactions found. Try another search or add one.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Type</th><th class="right">Amount</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $t):?><tr><td><?=e($t['transaction_date'])?></td><td><?=e($t['description']?:'—')?></td><td><?=e($t['category'])?></td><td><span class="type <?=$t['type']?>"><?=ucfirst(e($t['type']))?></span></td><td class="right <?=$t['type']==='income'?'green':'red'?>"><?=money($t['amount'])?></td><td><div class="actions-inline"><a href="transactions.php?action=edit&id=<?=(int)$t['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this transaction?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button class="link-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php end_page();?>
